//! Gaussian Blur fixtures generated by the pinned original renderer.
use filmcraft_project::{Param,ParamValue};
use filmcraft_render::{effects::{apply,FxCtx},image::Image};
use serde_json::json;
fn main(){
 let mut cases=vec![];
 for (w,h) in [(1,7),(7,1),(6,4),(18,10)] {for dimensions in 0..3u32 {for repeat in [false,true] {for blurriness in [0.0,0.6,2.0,7.0,3000.0] {
  let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();
  let input:Vec<[f32;4]>=rgba.chunks_exact(4).map(|p|{let a=p[3] as f32/255.0;[filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[1] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[2] as f32/255.0)*a,a]}).collect();
  let mut image=Image{w,h,px:input.iter().flatten().copied().collect()};
  let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="gaussian_blur").unwrap().instance();
  effect.params.insert("blurriness".into(),Param::new(ParamValue::Float(blurriness)));
  effect.params.insert("dimensions".into(),Param::new(ParamValue::Choice(dimensions)));
  effect.params.insert("repeat_edge".into(),Param::new(ParamValue::Bool(repeat)));
  let cx=FxCtx{t:filmcraft_time::Tick(0),px_scale:1.0,seconds:0.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
  apply(&mut image,&effect,&cx);
  cases.push(json!({"parameters":{"blurriness":blurriness,"dimensions":dimensions,"repeatEdge":repeat},"width":w,"height":h,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
 }}}}
 let mut media=vec![];
 for dimensions in 0..3u32 {for repeat in [false,true] {for tick in [0u64,250000,500000] {
  let a=128.0f32/255.0;let mut image=Image::filled(16,16,[a,a,a,a]);
  let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="gaussian_blur").unwrap().instance();
  effect.params.insert("blurriness".into(),Param::new(ParamValue::Float(tick as f64/500000.0*12.0)));
  effect.params.insert("dimensions".into(),Param::new(ParamValue::Choice(dimensions)));
  effect.params.insert("repeat_edge".into(),Param::new(ParamValue::Bool(repeat)));
  let cx=FxCtx{t:filmcraft_time::Tick(tick as i64),px_scale:1.0,seconds:0.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
  apply(&mut image,&effect,&cx);
  media.push(json!({"dimensions":dimensions,"repeatEdge":repeat,"localTick":tick,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
 }}}
 println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));
}
